contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint for the property-based test
    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(stakeAmount > 0 && withdrawAmount > 0, "positive amounts");

        // The test contract will act as a user interacting with c.
        // Approve and stake: since stakingToken is an external token, we cannot manipulate it here.
        // But we can only interact via c's public surface. We'll try to stake by calling stakeFor
        // However stakeFor will transfer tokens from msg.sender; msg.sender here is this test contract.
        // To avoid failing transfers in environments without real tokens, we first check that
        // stakingToken allows this contract to call stakeFor by attempting stake and catching revert.

        // Record pre-state
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        // Try to stake; if it reverts, we consider stake did not happen.
        bool stakeReverted;
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Record after potential stake
        uint256 totalAfterStake = c.totalSupply();
        uint256 balAfterStake = c.balanceOf(address(this));

        // Now attempt withdraw; capture whether it reverts
        bool withdrawReverted;
        try c.withdraw(withdrawAmount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Record post-withdraw state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        // General invariant: withdraw must not increase totalSupply or caller balance.
        // If withdraw succeeded (did not revert) then both totalSupply and balance cannot be greater than before withdraw.
        // If withdraw reverted then state should be unchanged by the withdraw attempt.
        // Because stake may or may not have happened, we express relation relative to the immediate pre-withdraw values.

        // Pre-withdraw values are totalAfterStake and balAfterStake. Assert that after withdraw:
        // 1) totalAfter <= totalAfterStake
        // 2) balAfter <= balAfterStake
        // 3) if withdrawReverted then totalAfter == totalAfterStake and balAfter == balAfterStake
        assert(
            totalAfter <= totalAfterStake &&
            balAfter <= balAfterStake &&
            (withdrawReverted ? (totalAfter == totalAfterStake && balAfter == balAfterStake) : true)
        );
    }

    receive() external payable {}
}

