contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: staker address, amount to stake
    // We must be the msg.sender passed to c.stakeFor, so we call stakeFor from this contract.
    function run(address staker, uint256 amount) public payable {
        require(staker != address(0), "staker not zero");
        // Precondition: ensure this contract has enough stakingToken balance if amount>0
        // We cannot mint tokens; but stakingToken.safeTransferFrom will be called with msg.sender == address(this)
        // The test assumes token allowances and balances may be zero; so we only assert behavior relative to revert/non-revert.

        // Read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(staker);

        bool reverted;
        // Calls that change state must be top-level. Use try/catch to capture revert.
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(staker);

        // General rule:
        // - If amount == 0 then stakeFor must revert (contract requires >0).
        // - If it did not revert then totalSupply and balance increased by exactly amount.
        // Note: If stakeFor reverts for other reasons (e.g., token transfer failure), then reverted==true and we cannot assert on deltas.
        // So assert: (amount==0) <=> reverted, and if not reverted then deltas equal amount.
        assert( (amount == 0 && reverted) ||
                (amount != 0 && !reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount) );
    }

    receive() external payable {}
}

