contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // we take distributor, rewardToken, and amount as inputs
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(distributor != address(0), "distributor nonzero");
        require(rewardToken != address(0), "rewardToken nonzero");

        // Ensure this contract has tokens approved and balance: we cannot mint tokens here, but we observe behavior via revert/non-revert and periodFinish.
        // Read before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = address(c).balance; // may be 0; for ERC20 transfers this won't change, but we still observe

        bool reverted;
        // notifyRewardAmount is external and requires caller == rewardDistributor and reward token registered and amount>0
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = address(c).balance;

        // General rule: if notifyRewardAmount did not revert then caller must have been the configured distributor (i.e., distributor must equal c.rewardDistributor())
        // and the reported periodFinish for the token is strictly greater than beforeFinish (advanced into the future or set) and greater or equal to block.timestamp
        // Otherwise (reverted) we make no claim about periodFinish change.
        // We express distributor equality by reading public getter.
        address currentDistributor = c.rewardDistributor();

        assert(reverted || (currentDistributor == distributor && afterFinish >= uint40(block.timestamp) && afterFinish > beforeFinish));
    }

    receive() external payable {}
}

