contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address staker, uint256 amount) public payable {
        require(staker != address(0));
        // Precondition: ensure this contract has enough of the staking token to transferFrom
        // But we cannot mint tokens here; the checker deploys c fresh. We therefore observe behavior
        // irrespective of token balances: stakeFor may revert. We assert the atomic relation.

        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(staker);

        // Attempt stakeFor; capture whether it reverted
        bool reverted;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(staker);

        // The general invariant: if call succeeded, both totalSupply and balance increase by exactly amount;
        // if it reverted, both remain equal to their previous values.
        assert((!reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount) || (reverted && afterTotal == beforeTotal && afterBal == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address staker, uint256 amount, bool claim) public payable {
        require(staker != address(0));

        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(staker);

        // Attempt withdraw as if called by staker: since the checker will call run once with msg.sender = deployer,
        // we simulate by invoking c.withdraw from this contract; the contract acts as msg.sender for c.
        // To match the semantics, we capture revert status
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(staker);

        // General rule: if withdraw succeeded and staker == msg.sender (i.e. this contract),
        // then totalSupply and balanceOf(this contract) decreased by amount; otherwise if it reverted,
        // they remain unchanged. Because we cannot change who msg.sender was when calling c.withdraw,
        // we express the rule in terms of the observed staker parameter: when staker equals address(this),
        // the call affects that balance; otherwise balances observed for arbitrary staker should be unchanged
        // by this withdraw call (since withdraw affects only msg.sender's balance).

        // Build conditions:
        bool stakerIsCaller = (staker == address(this));

        // When call succeeded and caller is the observed staker, both totals decrease by amount.
        // When call succeeded but caller is not the observed staker, observed balances must be unchanged.
        // When call reverted, observed values unchanged.
        assert(
            (reverted && afterTotal == beforeTotal && afterBal == beforeBal)
            || (!reverted && stakerIsCaller && afterTotal == beforeTotal - amount && afterBal == beforeBal - amount)
            || (!reverted && !stakerIsCaller && afterTotal == beforeTotal && afterBal == beforeBal)
        );
    }

    // allow receiving ETH if needed by c calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    // We take amount and recipient. This contract will be msg.sender for calls to c.
    function run(address recipient, uint256 amount) public payable {
        // preconditions: recipient must be non-zero and amount > 0 to avoid trivial reverts from require in stakeFor
        require(recipient != address(0));
        require(amount > 0);

        // Read before values for the observed recipient
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(recipient);

        // Attempt to call stakeFor as this contract (msg.sender == address(this))
        bool reverted;
        try c.stakeFor(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(recipient);

        // The general rule we assert:
        // If the call reverted, the observed totalSupply and recipient balance must be unchanged.
        // If the call did not revert, then totalSupply and recipient balance must have increased by amount.
        // Note: stakeFor requires msg.sender to transfer tokens in; since this test cannot guarantee
        // token approvals or balances, stakeFor might revert — covered by the reverted case.
        assert(
            (reverted && afterTotal == beforeTotal && afterBal == beforeBal)
            || (!reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that drives C.stakeFor and asserts the atomicity property
    // Parameters: recipient to receive stake, amount to stake.
    function run(address recipient, uint256 amount) public payable {
        // allow any recipient (including this contract), but amount must be > 0 because stakeFor reverts on 0
        require(amount > 0);

        // Observe before-state through public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(recipient);

        // Call stakeFor and record whether it reverted
        bool reverted;
        try c.stakeFor(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(recipient);

        // Assert the general atomicity rule: either unchanged on revert, or increased by exactly amount on success
        assert(
            (reverted && afterTotal == beforeTotal && afterBal == beforeBal)
            || (!reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

