contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that acts as the property-based test
    // params: staker address (as caller via msg.sender in c calls is this contract), amount to stake,
    // and an address to be used as the _for parameter in stakeFor.
    function run(address _for, uint256 _amount) public payable {
        // ensure this contract has enough staking tokens to transfer when stakeFor is called
        // We cannot mint tokens here; assume the stakingToken used by c has allowance/transferFrom behavior
        // To avoid interfering with external constraints, we only enforce a logical precondition that
        // _amount fits in uint256 (always true). No require on c's state.
        require(_for != address(0), "invalid for");

        // Read pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(_for);

        bool reverted;
        // Call stakeFor. It will attempt to transferFrom(msg.sender,...). msg.sender is this contract.
        // The call might revert (e.g., insufficient allowance/balance or amount==0). Capture that.
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state (callable even if stakeFor reverted)
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(_for);

        // General rule:
        // - If stakeFor reverted then no change in totalSupply and no change in _for balance.
        // - If stakeFor did not revert then afterTotal == beforeTotal + _amount and afterBalance == beforeBalance + _amount.
        // This asserts preservation on revert and proper accumulation on success.
        assert(
            (reverted && afterTotal == beforeTotal && afterBalance == beforeBalance) ||
            (!reverted && afterTotal == beforeTotal + _amount && afterBalance == beforeBalance + _amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
