    constructor(C _c) { c = _c; tester = address(this); }

    // Single public entry performing the property-based test.
    // Params:
    // - staker: address whose stake will be read (balanceOf)
    // - amount: amount to attempt to withdraw
    // - claim: whether to request claiming rewards in the withdraw call
    function run(address staker, uint256 amount, bool claim) public payable {
        require(staker != address(0), "staker nonzero");

        // Observe pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeContractTokenBal = address(c).balance; // ETH balance (may be 0)

        // Also observe the stakingToken balance held by the contract via public stakingToken getter and IERC20.balanceOf view
        address stakingTokenAddr = address(c.stakingToken());
        uint256 beforeStakingTokenBal = 0;
        // We may call balanceOf on the ERC20; do it in a try/catch since token may be non-compliant
        try IERC20(stakingTokenAddr).balanceOf(address(c)) returns (uint256 bt) {
            beforeStakingTokenBal = bt;
        } catch {
            // If the token reverts, set a sentinel that will make the final assertion rely only on observed c.totalSupply and balances
            beforeStakingTokenBal = type(uint256).max;
        }

        bool didRevert;
        // Call withdraw; capture whether it reverts
        try c.withdraw(amount, claim) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);
        uint256 afterStakingTokenBal = 0;
        bool stakingTokenBalObserved = true;
        if (beforeStakingTokenBal == type(uint256).max) {
            stakingTokenBalObserved = false;
        } else {
            try IERC20(stakingTokenAddr).balanceOf(address(c)) returns (uint256 at) {
                afterStakingTokenBal = at;
            } catch {
                stakingTokenBalObserved = false;
            }
        }

        // General rule asserted:
        // - If withdraw reverted: totalSupply and staker balance are unchanged.
        // - If withdraw succeeded: totalSupply and staker balance decreased by exactly amount.
        // Additionally, if we were able to read stakingToken balances, then the contract's stakingToken balance increased by exactly amount on success, and unchanged on revert.
        assert(
            (didRevert && afterTotal == beforeTotal && afterBalance == beforeBalance && (!stakingTokenBalObserved || afterStakingTokenBal == beforeStakingTokenBal))
            ||
            (!didRevert && afterTotal + amount == beforeTotal && afterBalance + amount == beforeBalance && (!stakingTokenBalObserved || afterStakingTokenBal == beforeStakingTokenBal + amount))
        );
    }

    // No-op receive to allow sending ETH to this contract if needed externally
    receive() external payable {}
}

