    function run(address rewardsToken, uint256 amount) public payable {
        require(rewardsToken != address(0), "token nonzero");

        // Observe pre-state: recorded period finish and contract token balance (if observable)
        uint40 beforeFinish = c.rewardPeriodFinish(rewardsToken);
        address tokenAddr = rewardsToken;
        uint256 beforeTokenBal = 0;
        bool tokenBalanceReadable = true;
        // Try to read ERC20 balanceOf; if it reverts, mark as not readable
        try IERC20(tokenAddr).balanceOf(address(c)) returns (uint256 bt) {
            beforeTokenBal = bt;
        } catch {
            tokenBalanceReadable = false;
        }

