    // parameters: distributor must be msg.sender when calling notifyRewardAmount; amount > 0; rewardToken must have been added previously
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // Deploy-time owner is this contract (per C constructor behavior), so add the reward token first
        c.addReward(rewardToken);

        // set reward distributor to the provided distributor
        c.setRewardDistributor(distributor);

        // record previous periodFinish and contract token balance
        uint40 prevFinish = c.rewardPeriodFinish(rewardToken);
        uint256 prevBalance = IERC20(rewardToken).balanceOf(address(c));

        // Transfer tokens from this contract to distributor so distributor can call notifyRewardAmount
        // We require that this contract has enough tokens to approve and transfer from; the checker will ensure balances
        // Approve c to pull from distributor: but we cannot make arbitrary external accounts transfer tokens here.
        // Instead we act as the distributor by having this contract be the distributor in a call to c.notifyRewardAmount.
        // So require distributor == address(this)
        require(distributor == address(this), "distributor must be this contract for the test");

        // Now approve c to pull 'amount' tokens from this contract
        IERC20(rewardToken).approve(address(c), amount);

        // Call notifyRewardAmount as the distributor (this contract)
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 newFinish = c.rewardPeriodFinish(rewardToken);
        uint256 newBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule: if notifyRewardAmount did not revert then the periodFinish is at least prevFinish and the contract's token balance increased by amount
        assert(reverted || (newFinish >= prevFinish && newBalance >= prevBalance + amount));
    }

    receive() external payable {}
}

