        // As the deployer of c, this contract is the owner and can call owner-only functions.
        // Add the reward token (owner-only). This sets lastUpdateTime != 0.
        c.addReward(rewardToken);

        // Make this contract the reward distributor so notifyRewardAmount can be called by it.
        c.setRewardDistributor(address(this));

        // Call notifyRewardAmount as distributor. The call may transfer tokens from this contract
        // via SafeERC20.safeTransferFrom; the test assumes external environment may have set allowances/balances.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, addAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable values from c.
        uint40 finish = c.rewardPeriodFinish(rewardToken);
        uint256 rpt;
        bool rptReverted = false;
        // rewardPerToken is view; call it but catch potential revert (shouldn't revert).
        try c.rewardPerToken(rewardToken) returns (uint256 v) {
            rpt = v;
        } catch {
            rptReverted = true;
            rpt = 0;
        }

        // General rule: when notifyRewardAmount is invoked by the designated distributor with amount>0
        // the call must not revert and the recorded periodFinish must be >= block.timestamp, and rewardPerToken view must be callable.
        // We assert the implication: if notifyRewardAmount did NOT revert then finish >= now and rewardPerToken did not revert.
        assert(reverted || (uint256(finish) >= block.timestamp && !rptReverted));
    }

    receive() external payable {}
}

