contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We take three params: who (address to stake for), amount to stake, and approveAmount to set allowance from msg.sender
    function run(address forAddress, uint256 amount, uint256 approveAmount) public payable {
        // preconditions: amount must be > 0 to exercise stake path; approveAmount is what this test will set as allowance
        require(amount > 0);

        // The InvMutTest contract is msg.sender for c calls. We need to have tokens in this contract and approve c to pull them.
        // We cannot mint tokens here; instead we rely on the staking token's transferFrom to succeed only if allowance and balance permit.
        // To make the transferFrom succeed in some executions, attempt to approve c to spend approveAmount from this contract.
        // Approve the staking token to allow c to pull up to approveAmount.
        // Note: token.approve is external; call it on the token contract. We do not assert its success here; safeTransferFrom inside c will revert if transfer fails.
        token.approve(address(c), approveAmount);

        // Read pre-state observables
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddress);
        uint256 contractTokenBalance = token.balanceOf(address(this));

        // Try to call stakeFor from this contract (msg.sender of c will be this contract). Catch revert.
        bool reverted;
        try c.stakeFor(forAddress, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state observables
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddress);
        uint256 contractTokenBalanceAfter = token.balanceOf(address(this));

        // General rule asserted:
        // If stakeFor did not revert then totalSupply increased by amount and the beneficiary balance increased by amount,
        // and the staking token balance of this contract decreased by at least amount (i.e. tokens were transferred out).
        // If stakeFor reverted then no change to those observed values occurs (conservative: require that either revert happened or expected increments hold).
        assert(
            reverted
            ? (totalAfter == totalBefore && balAfter == balBefore && contractTokenBalanceAfter == contractTokenBalance)
            : (totalAfter == totalBefore + amount && balAfter == balBefore + amount && contractTokenBalanceAfter + amount <= contractTokenBalance)
        );
    }

    // receive not needed but allowed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: beneficiary to credit, amount to stake, allowance to set on staking token
    function run(address forAddress, uint256 amount, uint256 approveAmount) public payable {
        require(amount > 0);

        // record pre-state (only view calls allowed here)
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddress);
        uint256 tokenBalBefore = token.balanceOf(address(this));

        // set allowance so that stakeFor may succeed
        token.approve(address(c), approveAmount);

        // perform the state-changing call on c at top-level, catching revert
        bool reverted;
        try c.stakeFor(forAddress, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddress);
        uint256 tokenBalAfter = token.balanceOf(address(this));

        // If call reverted, observable values should be unchanged. Otherwise total and balance increase exactly by amount
        // and token balance of this contract decreased by at least amount (transferFrom could succeed moving exactly amount).
        assert(
            reverted
                ? (totalAfter == totalBefore && balAfter == balBefore && tokenBalAfter == tokenBalBefore)
                : (totalAfter == totalBefore + amount && balAfter == balBefore + amount && tokenBalBefore >= tokenBalAfter && tokenBalBefore - tokenBalAfter >= amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: rewardToken (must be previously added), amount to notify, caller (must be rewardDistributor)
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(rewardToken != address(0));

        // Precondition setup: set rewardDistributor to distributor (owner-only). The test contract is the owner of c.
        c.setRewardDistributor(distributor);

        // Ensure reward token is known: owner must call addReward. InvMutTest (owner) adds rewardToken if not added yet.
        // addReward will revert if already exists, so guard by a try/catch.
        bool added = false;
        try c.addReward(rewardToken) {
            added = true;
        } catch {
            added = false;
        }

        // Observe pre-values
        uint256 balanceBefore = IERC20(rewardToken).balanceOf(address(c));
        uint40 finishBefore = c.rewardPeriodFinish(rewardToken);

        // Call notifyRewardAmount from distributor by making the test contract call c.notifyRewardAmount via a low-level call pattern:
        // We need msg.sender to be distributor. Since the checker runs run(...) once and msg.sender is this contract,
        // we simulate the distributor calling by using Address.functionCall on c from this contract is not possible.
        // Instead, we require that distributor equals address(this) so that the call originates from this contract (the distributor).
        // This is allowed by the precondition below.
        require(distributor == address(this));
        require(amount > 0);

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = IERC20(rewardToken).balanceOf(address(c));
        uint40 finishAfter = c.rewardPeriodFinish(rewardToken);

        // General rule: if call reverted then observable state unchanged; otherwise contract's token balance increased by exactly amount
        // and periodFinish advanced (strictly greater than before).
        assert(
            reverted
                ? (balanceAfter == balanceBefore && finishAfter == finishBefore)
                : (balanceAfter == balanceBefore + amount && finishAfter > finishBefore)
        );
    }

    receive() external payable {}
}

