    // then rewardPeriodFinish(token) strictly increases (becomes > old finish) and token is
    // known in rewardTokens (i.e., rewardPeriodFinish before was non-zero). If it reverts,
    // the observable periodFinish must remain equal to the prior value.
    function run(address rewardToken, uint256 amount) public payable {
