        // But in this test msg.sender is this contract. We do not try to change c.rewardDistributor.
        // So call may revert (not distributor) or may succeed if the Deployed c had distributor set to this.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
