        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // If it reverted, observable periodFinish must be unchanged.
        // If it did not revert, then beforeFinish must have been non-zero (token known) and afterFinish > beforeFinish.
        assert(
